import { MakeLogicType, afterMount, kea, key, path, props, reducers } from 'kea'
import { loaders } from 'kea-loaders'

import { errorTrackingSettingsRetrieveSettingsRetrieve } from '../../../generated/api'
import type { ErrorTrackingSettingsApi } from '../../../generated/api.schemas'

export interface AdaptiveIngestionLogicProps {
    projectId: string
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface adaptiveIngestionLogicValues {
    settings: ErrorTrackingSettingsApi | null
    settingsError: boolean
    settingsLoading: boolean
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface adaptiveIngestionLogicActions {
    loadSettings: () => any
    loadSettingsFailure: (
        error: string,
        errorObject?: any
    ) => {
        error: string
        errorObject?: any
    }
    loadSettingsSuccess: (
        settings: ErrorTrackingSettingsApi,
        payload?: any
    ) => {
        settings: ErrorTrackingSettingsApi
        payload?: any
    }
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface adaptiveIngestionLogicMeta {
    key: string
}

export type adaptiveIngestionLogicType = MakeLogicType<
    adaptiveIngestionLogicValues,
    adaptiveIngestionLogicActions,
    AdaptiveIngestionLogicProps,
    adaptiveIngestionLogicMeta
>

export const adaptiveIngestionLogic = kea<adaptiveIngestionLogicType>([
    props({} as AdaptiveIngestionLogicProps),
    key((props) => props.projectId),
    path((key) => ['products', 'error_tracking', 'scenes', 'adaptive_ingestion', 'adaptiveIngestionLogic', key]),
    loaders(({ props }) => ({
        settings: [
            null as ErrorTrackingSettingsApi | null,
            {
                loadSettings: async (): Promise<ErrorTrackingSettingsApi> =>
                    errorTrackingSettingsRetrieveSettingsRetrieve(props.projectId),
            },
        ],
    })),
    reducers({
        settingsError: [false, { loadSettingsFailure: () => true, loadSettingsSuccess: () => false }],
    }),
    afterMount(({ actions, props }): void => {
        if (props.projectId) {
            actions.loadSettings()
        }
    }),
])
